/** Fastify exposes HEAD for its GET registrations; Node's device handler does not. */
export const httpRoutes: HttpRoute[] = registeredHttpRoutes.flatMap(route => {
  if (route.method !== 'GET' || !['http', 'sse', 'web'].includes(route.transport)) return [route]
  return [route, { ...route, method: 'HEAD', implicitHead: true as const }]
})

/** Separate per-execution listeners; main API MCP coverage cannot satisfy these mounts. */
export const runtimeHttpRoutes: HttpRoute[] = [
  { method: 'POST', path: '/mcp/files', lane: 'A2', transport: 'native-files',
    provenance: 'apps/api/src/modules/files/tools/nativeServer.ts:15' },
  { method: 'POST', path: '/mcp', lane: 'R', transport: 'worker-mcp',
    provenance: 'apps/api/src/modules/runs/remote/workerMcpEndpoint.ts:114' },
]
